  x_localFetchFailedReason,
  x_localMissingKeyReason,
  x_localMissingUrlReason,
  x_localProviderName,
} from "./localProvider.js";

type PiRegistryModel = ReturnType<ModelRegistry["getAll"]>[number];

const x_supportedBuiltInProviders = new Set(["openai"]);

export interface SheafModelRegistryBundle
{
  authStorage: AuthStorage;
  modelRegistry: ModelRegistry;
  localProviderState: LocalProviderState;
}

export interface CreateSheafModelRegistryOptions extends FetchLocalModelsOptions
{
  localProviderState?: LocalProviderState;
}

export class ModelValidationError extends Error
{
  readonly code: string;

  constructor(code: string, message: string)
  {
    super(message);
    this.name = "ModelValidationError";
    this.code = code;
  }
}

export async function CreateSheafModelRegistry(
  config: SheafChatConfig,
  authStorage: AuthStorage,
  options: CreateSheafModelRegistryOptions = {},
): Promise<SheafModelRegistryBundle>
{
  const modelsJsonPath = ResolveSheafModelsJsonPath(config);
  const modelRegistry = ModelRegistry.create(authStorage, modelsJsonPath);
  const localProviderState =
    options.localProviderState ?? await FetchLocalModels(config, options);

  if (config.openAiApiKey !== null)
  {
    authStorage.setRuntimeApiKey("openai", config.openAiApiKey);
  }

  if (config.localInferenceApiKey !== null)
  {
    authStorage.setRuntimeApiKey(x_localProviderName, config.localInferenceApiKey);
  }

  RegisterLocalProviderOnRegistry(modelRegistry, config, localProviderState);

  return {
    authStorage,
    modelRegistry,
    localProviderState,
  };
}

export function MapPiModelToMetadata(
  model: PiRegistryModel,
  config: SheafChatConfig,
  modelRegistry: ModelRegistry,
  localProviderState: LocalProviderState,
): ModelMetadata
{
  const available =
    model.provider === x_localProviderName
      ? IsLocalModelAvailable(config, localProviderState) &&
        localProviderState.models.some((entry) => entry.id === model.id)
      : modelRegistry.hasConfiguredAuth(model);

  const metadata: ModelMetadata = {
    provider: model.provider,
    id: model.id,
    displayName: model.name ?? model.id,
    contextTokens:
      typeof model.contextWindow === "number" && Number.isFinite(model.contextWindow)
        ? model.contextWindow
        : undefined,
    available,
  };

  if (!available && model.provider === x_localProviderName)
  {
    metadata.unavailableReason =
      localProviderState.unavailableReason ?? x_localFetchFailedReason;
  }

  return metadata;
}

function IsSheafSupportedModel(model: PiRegistryModel): boolean
{
  return model.provider === x_localProviderName ||
    x_supportedBuiltInProviders.has(model.provider);
}

export function ListModels(
  config: SheafChatConfig,
  modelRegistry: ModelRegistry,
  localProviderState: LocalProviderState,
): ModelMetadata[]
{
  const models = modelRegistry.getAll().filter(IsSheafSupportedModel);
  const metadata = models.map((model) =>
    MapPiModelToMetadata(model, config, modelRegistry, localProviderState));

  const seen = new Set<string>();
  const merged: ModelMetadata[] = [];

  for (const entry of metadata)
  {
    const key = `${entry.provider}:${entry.id}`;
    if (seen.has(key))
    {
      continue;
    }

    seen.add(key);
    merged.push(entry);
  }

  merged.sort((left, right) =>
  {
    const providerCompare = left.provider.localeCompare(right.provider);
    if (providerCompare !== 0)
    {
      return providerCompare;
    }

    return left.id.localeCompare(right.id);
  });

  return merged;
}

export function ValidateModelSelection(
  config: SheafChatConfig,
  modelRegistry: ModelRegistry,
  localProviderState: LocalProviderState,
  selection: ModelReference,
): ModelMetadata
{
  const model = modelRegistry.find(selection.provider, selection.id);

  if (model === undefined || !IsSheafSupportedModel(model))
  {
    throw new ModelValidationError(
      "model_not_found",
      `model not found: ${selection.provider}/${selection.id}`,
    );
  }

  const metadata = MapPiModelToMetadata(
    model,
    config,
    modelRegistry,
    localProviderState,
  );

  if (!metadata.available)
  {
    throw new ModelValidationError(
      "model_unavailable",
      metadata.unavailableReason
        ? `model unavailable: ${metadata.unavailableReason}`
        : `model unavailable: ${selection.provider}/${selection.id}`,
    );
  }

  return metadata;
}

import { mkdir, readdir, stat } from "node:fs/promises";
import path from "node:path";

import type { PileSummary } from "../shared/types.js";
import { StorageError } from "./errors.js";
import {
  AssertPilePathWithinRoot,
  CreateStoragePaths,
  ResolveManifestFilePath,
  ResolvePileDirectory,
  type StoragePaths,
} from "./paths.js";
import { ValidatePileName } from "./validation.js";

export type { StoragePaths };

async function ReadManifestUpdatedAt(manifestPath: string): Promise<string | null>
{
  try
  {
    const manifestStat = await stat(manifestPath);
    return manifestStat.mtime.toISOString();
  }
  catch
  {
    return null;
  }
}

export async function CreatePile(paths: StoragePaths, pile: string): Promise<PileSummary>
{
  const validatedPile = ValidatePileName(pile);
  const pileDirectory = ResolvePileDirectory(paths, validatedPile);
  await mkdir(pileDirectory, { recursive: true });
  await AssertPilePathWithinRoot(paths, pileDirectory);

  return {
    pile: validatedPile,
    sessionCount: 0,
    latestUpdatedAt: null,
  };
}

export async function ListPiles(paths: StoragePaths): Promise<PileSummary[]>
{
  await mkdir(paths.pilesDir, { recursive: true });

  let entries: string[];

  try
  {
    entries = await readdir(paths.pilesDir);
  }
  catch
  {
    return [];
  }

  const summaries: PileSummary[] = [];

  for (const entry of entries)
  {
    let validatedPile: string;

    try
    {
      validatedPile = ValidatePileName(entry);
    }
    catch
    {
      continue;
    }

    const pileDirectory = path.join(paths.pilesDir, validatedPile);
    const pileStat = await stat(pileDirectory);

    if (!pileStat.isDirectory())
    {
      continue;
    }

    let sessionCount = 0;
    let latestUpdatedAt: string | null = null;
    const pileEntries = await readdir(pileDirectory);

    for (const pileEntry of pileEntries)
    {
      if (!pileEntry.endsWith(".manifest.json"))
      {
        continue;
      }

      sessionCount += 1;
      const manifestPath = path.join(pileDirectory, pileEntry);
      const updatedAt = await ReadManifestUpdatedAt(manifestPath);

      if (updatedAt !== null && (latestUpdatedAt === null || updatedAt > latestUpdatedAt))
      {
        latestUpdatedAt = updatedAt;
      }
    }

    summaries.push({
      pile: validatedPile,
      sessionCount,
      latestUpdatedAt,
    });
  }

  summaries.sort((left, right) => left.pile.localeCompare(right.pile));
  return summaries;
}

export async function EnsurePileExists(paths: StoragePaths, pile: string): Promise<void>
{
  const validatedPile = ValidatePileName(pile);
  const pileDirectory = ResolvePileDirectory(paths, validatedPile);

  try
  {
    const pileStat = await stat(pileDirectory);

    if (!pileStat.isDirectory())
    {
      throw new StorageError("pile_not_found", `pile not found: ${validatedPile}`);
    }
  }
  catch (error)
  {
    if (error instanceof StorageError)
    {
      throw error;
    }

    throw new StorageError("pile_not_found", `pile not found: ${validatedPile}`);
  }

  await AssertPilePathWithinRoot(paths, pileDirectory);
}

export async function ManifestExists(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<boolean>
{
  try
  {
    await stat(ResolveManifestFilePath(paths, pile, sessionId));
    return true;
  }
  catch
  {
    return false;
  }
}

import { readFile, readdir, writeFile } from "node:fs/promises";

import type {
  SessionManifest,
  UpdateManifestInput,
  WriteInitialManifestInput,
} from "../shared/types.js";
import { x_manifestSchemaVersion } from "../shared/types.js";
import { StorageError } from "./errors.js";
import { EnsurePileExists } from "./piles.js";
import {
  ManifestSessionFileReference,
  ResolveManifestFilePath,
  ResolvePileDirectory,
  type StoragePaths,
} from "./paths.js";
import { ValidateSessionId } from "./validation.js";

function ParseManifest(raw: string, pile: string, sessionId: string): SessionManifest
{
  let parsed: SessionManifest;

  try
  {
    parsed = JSON.parse(raw) as SessionManifest;
  }
  catch
  {
    throw new StorageError("invalid_manifest", "manifest is not valid JSON");
  }

  if (parsed.pile !== pile || parsed.sessionId !== sessionId)
  {
    throw new StorageError("invalid_manifest", "manifest identity does not match request");
  }

  return parsed;
}

export async function ReadManifest(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<SessionManifest>
{
  await EnsurePileExists(paths, pile);
  const validatedSessionId = ValidateSessionId(sessionId);
  const manifestPath = ResolveManifestFilePath(paths, pile, validatedSessionId);

  let raw: string;

  try
  {
    raw = await readFile(manifestPath, "utf8");
  }
  catch
  {
    throw new StorageError(
      "manifest_not_found",
      `manifest not found for session ${validatedSessionId}`,
    );
  }

  return ParseManifest(raw, pile, validatedSessionId);
}

export async function ListSessionManifests(
  paths: StoragePaths,
  pile: string,
): Promise<SessionManifest[]>
{
  await EnsurePileExists(paths, pile);
  const pileDirectory = ResolvePileDirectory(paths, pile);
  const entries = await readdir(pileDirectory);
  const manifests: SessionManifest[] = [];

  for (const entry of entries)
  {
    if (!entry.endsWith(".manifest.json"))
    {
      continue;
    }

    const sessionId = entry.slice(0, -".manifest.json".length);

    try
    {
      ValidateSessionId(sessionId);
      manifests.push(await ReadManifest(paths, pile, sessionId));
    }
    catch
    {
      continue;
    }
  }

  manifests.sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
  return manifests;
}

export async function WriteInitialManifest(
  paths: StoragePaths,
  input: WriteInitialManifestInput,
): Promise<SessionManifest>
{
  await EnsurePileExists(paths, input.pile);
  const validatedSessionId = ValidateSessionId(input.sessionId);
  const manifestPath = ResolveManifestFilePath(paths, input.pile, validatedSessionId);
  const now = new Date().toISOString();
  const manifest: SessionManifest = {
    schemaVersion: x_manifestSchemaVersion,
    pile: input.pile,
    sessionId: validatedSessionId,
    chatName: input.chatName,
    description: input.description,
    rootDirectory: input.rootDirectory,
    createdAt: now,
    updatedAt: now,
    lastOpenedAt: now,
    model: input.model,
    pi: {
      sessionFile: ManifestSessionFileReference(paths.repoRoot, input.pile, validatedSessionId),
      extensionVersion: input.extensionVersion,
    },
    history: {
      messageCount: input.messageCount ?? 0,
      lastSequence: input.lastSequence ?? 0,
    },
  };

  await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");
  return manifest;
}

export async function UpdateManifest(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
  update: UpdateManifestInput,
): Promise<SessionManifest>
{
  const manifest = await ReadManifest(paths, pile, sessionId);
  const updated: SessionManifest = {
    ...manifest,
    chatName: update.chatName ?? manifest.chatName,
    description: update.description ?? manifest.description,
    rootDirectory: update.rootDirectory ?? manifest.rootDirectory,
    model: update.model ?? manifest.model,
    lastOpenedAt: update.lastOpenedAt ?? manifest.lastOpenedAt,
    updatedAt: new Date().toISOString(),
    history: {
      messageCount: update.messageCount ?? manifest.history.messageCount,
      lastSequence: update.lastSequence ?? manifest.history.lastSequence,
    },
  };

  const manifestPath = ResolveManifestFilePath(paths, pile, sessionId);
  await writeFile(manifestPath, `${JSON.stringify(updated, null, 2)}\n`, "utf8");
  return updated;
}

import type { HistoryPage, HistoryPageRequest, SessionLogEntry } from "../shared/types.js";
import type { ChatEnvelope } from "../shared/envelope.js";
import { StorageError } from "./errors.js";
import { CollectSessionLogEntries } from "./sessionLog.js";
import type { StoragePaths } from "./paths.js";
import { ValidateSessionId } from "./validation.js";

export const x_defaultHistoryLimit = 50;
export const x_maxHistoryLimit = 200;

function ClampHistoryLimit(limit: number | undefined): number
{
  if (limit === undefined || !Number.isFinite(limit) || limit <= 0)
  {
    return x_defaultHistoryLimit;
  }

  return Math.min(Math.floor(limit), x_maxHistoryLimit);
}

function EnvelopesFromEntries(entries: SessionLogEntry[]): ChatEnvelope[]
{
  return entries.map((entry) => entry.envelope);
}

function SequenceBounds(entries: SessionLogEntry[]): {
  oldestSequence: number | null;
  newestSequence: number | null;
}
{
  if (entries.length === 0)
  {
    return {
      oldestSequence: null,
      newestSequence: null,
    };
  }

  return {
    oldestSequence: entries[0].sequence,
    newestSequence: entries[entries.length - 1].sequence,
  };
}

function ValidateHistoryRequest(request: HistoryPageRequest): HistoryPageRequest
{
  const hasBefore = request.before !== undefined;
  const hasAfter = request.after !== undefined;

  if (hasBefore && hasAfter)
  {
    throw new StorageError(
      "invalid_history_request",
      "history request cannot include both before and after cursors",
    );
  }

  return request;
}

function BuildLatestPage(entries: SessionLogEntry[], limit: number): HistoryPage
{
  const pageEntries = entries.slice(Math.max(0, entries.length - limit));
  const bounds = SequenceBounds(pageEntries);
  const allBounds = SequenceBounds(entries);

  return {
    direction: "latest",
    envelopes: EnvelopesFromEntries(pageEntries),
    oldestSequence: bounds.oldestSequence,
    newestSequence: bounds.newestSequence ?? allBounds.newestSequence,
    hasMoreBefore: entries.length > pageEntries.length,
    hasMoreAfter: false,
  };
}

function BuildBeforePage(
  entries: SessionLogEntry[],
  before: number,
  limit: number,
): HistoryPage
{
  const olderEntries = entries.filter((entry) => entry.sequence < before);
  const pageEntries = olderEntries.slice(Math.max(0, olderEntries.length - limit));
  const bounds = SequenceBounds(pageEntries);
  const pageNewest = bounds.newestSequence;
  const hasMoreAfter =
    pageNewest !== null &&
    entries.some((entry) => entry.sequence > pageNewest && entry.sequence < before);

  return {
    direction: "before",
    envelopes: EnvelopesFromEntries(pageEntries),
    oldestSequence: bounds.oldestSequence,
    newestSequence: bounds.newestSequence,
    hasMoreBefore: olderEntries.length > pageEntries.length,
    hasMoreAfter,
  };
}

function BuildAfterPage(
  entries: SessionLogEntry[],
  after: number,
  limit: number,
): HistoryPage
{
  const newerEntries = entries.filter((entry) => entry.sequence > after);
  const pageEntries = newerEntries.slice(0, limit);
  const bounds = SequenceBounds(pageEntries);
  const allBounds = SequenceBounds(entries);

  return {
    direction: "after",
    envelopes: EnvelopesFromEntries(pageEntries),
    oldestSequence: bounds.oldestSequence,
    newestSequence: bounds.newestSequence ?? allBounds.newestSequence,
    hasMoreAfter: newerEntries.length > pageEntries.length,
    hasMoreBefore: false,
  };
}

export async function ReadHistoryPage(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
  request: HistoryPageRequest = {},
): Promise<HistoryPage>
{
  const validatedSessionId = ValidateSessionId(sessionId);
  const validatedRequest = ValidateHistoryRequest(request);
  const limit = ClampHistoryLimit(validatedRequest.limit);
  const entries = await CollectSessionLogEntries(paths, pile, validatedSessionId);

  if (validatedRequest.before !== undefined)
  {
    return BuildBeforePage(entries, validatedRequest.before, limit);
  }

  if (validatedRequest.after !== undefined)
  {
    return BuildAfterPage(entries, validatedRequest.after, limit);
  }

  return BuildLatestPage(entries, limit);
}

import type { AguiEvent, AguiSnapshotMessage } from "./types.js";

interface ToolCallSnapshot
{
  id: string;
  name: string;
  args: string;
  result: string | null;
}

interface SnapshotBuilderState
{
  messages: Map<string, AguiSnapshotMessage>;
  order: string[];
  finalizedIds: Set<string>;
  openText: Map<string, { role: string; content: string; timestamp?: number }>;
  openReasoning: Map<string, { content: string; timestamp?: number }>;
  openTools: Map<string, ToolCallSnapshot>;
  toolParents: Map<string, string>;
  toolResults: Map<string, string>;
}

function CreateSnapshotState(): SnapshotBuilderState
{
  return {
    messages: new Map(),
    order: [],
    finalizedIds: new Set(),
    openText: new Map(),
    openReasoning: new Map(),
    openTools: new Map(),
    toolParents: new Map(),
    toolResults: new Map(),
  };
}

function TrackFirstSeen(state: SnapshotBuilderState, messageId: string): void
{
  if (!state.order.includes(messageId))
  {
    state.order.push(messageId);
  }
}

function UpsertMessage(state: SnapshotBuilderState, message: AguiSnapshotMessage): void
{
  const messageId = String(message.id);
  TrackFirstSeen(state, messageId);
  state.messages.set(messageId, message);
}

function FinalizeAssistantToolCalls(state: SnapshotBuilderState, parentMessageId: string): ToolCallSnapshot[]
{
  const toolCalls: ToolCallSnapshot[] = [];

  for (const [toolCallId, toolCall] of state.openTools.entries())
  {
    if (state.toolParents.get(toolCallId) !== parentMessageId)
    {
      continue;
    }

    toolCalls.push({
      id: toolCallId,
      name: toolCall.name,
      args: toolCall.args,
      result: state.toolResults.get(toolCallId) ?? toolCall.result,
    });
  }

  return toolCalls;
}

function ApplyAguiEvent(state: SnapshotBuilderState, event: AguiEvent): void
{
  const eventType = event.type;

  if (eventType === "TEXT_MESSAGE_START")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    TrackFirstSeen(state, messageId);
    state.openText.set(messageId, {
      role: String(event.role ?? "assistant"),
      content: "",
      timestamp: typeof event.timestamp === "number" ? event.timestamp : undefined,
    });
    return;
  }

  if (eventType === "TEXT_MESSAGE_CONTENT")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    const open = state.openText.get(messageId) ?? {
      role: "assistant",
      content: "",
    };
    open.content += String(event.delta ?? "");
    state.openText.set(messageId, open);
    return;
  }

  if (eventType === "TEXT_MESSAGE_END")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    const open = state.openText.get(messageId);

    if (open === undefined)
    {
      return;
    }

    const snapshot: AguiSnapshotMessage = {
      id: messageId,
      role: open.role,
      content: open.content,
    };

    if (open.timestamp !== undefined)
    {
      snapshot.timestamp = open.timestamp;
    }

    if (open.role === "assistant")
    {
      const toolCalls = FinalizeAssistantToolCalls(state, messageId);

      if (toolCalls.length > 0)
      {
        snapshot.toolCalls = toolCalls.map((toolCall) => ({
          id: toolCall.id,
          name: toolCall.name,
          args: toolCall.args,
          result: toolCall.result,
        }));
      }
    }

    UpsertMessage(state, snapshot);
    state.finalizedIds.add(messageId);
    state.openText.delete(messageId);
    return;
  }

  if (eventType === "REASONING_MESSAGE_START")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    TrackFirstSeen(state, messageId);
    state.openReasoning.set(messageId, {
      content: "",
      timestamp: typeof event.timestamp === "number" ? event.timestamp : undefined,
    });
    return;
  }

  if (eventType === "REASONING_MESSAGE_CONTENT")
  {
    const messageId = String(event.messageId);
    const open = state.openReasoning.get(messageId) ?? { content: "" };
    open.content += String(event.delta ?? "");
    state.openReasoning.set(messageId, open);
    return;
  }

  if (eventType === "REASONING_MESSAGE_END")
  {
    const messageId = String(event.messageId);
    const open = state.openReasoning.get(messageId);

    if (open === undefined)
    {
      return;
    }

    const snapshot: AguiSnapshotMessage = {
      id: messageId,
      role: "reasoning",
      content: open.content,
    };

    if (open.timestamp !== undefined)
    {
      snapshot.timestamp = open.timestamp;
    }

    UpsertMessage(state, snapshot);
    state.finalizedIds.add(messageId);
    state.openReasoning.delete(messageId);
    return;
  }

  if (eventType === "TOOL_CALL_START")
  {
    const toolCallId = String(event.toolCallId);

    if (event.parentMessageId !== undefined)
    {
      TrackFirstSeen(state, String(event.parentMessageId));
    }

    state.openTools.set(toolCallId, {
      id: toolCallId,
      name: String(event.toolCallName ?? "tool"),
      args: "",
      result: null,
    });

    if (event.parentMessageId !== undefined)
    {
      state.toolParents.set(toolCallId, String(event.parentMessageId));
    }

    return;
  }

  if (eventType === "TOOL_CALL_ARGS")
  {
    const toolCallId = String(event.toolCallId);
    const toolCall = state.openTools.get(toolCallId);

    if (toolCall !== undefined)
    {
      toolCall.args += String(event.delta ?? "");
    }

    return;
  }

  if (eventType === "TOOL_CALL_RESULT")
  {
    const toolCallId = String(event.toolCallId);
    const messageId = String(event.messageId ?? `${toolCallId}:result`);
    const content = String(event.content ?? "");
    state.toolResults.set(toolCallId, content);

    const snapshot: AguiSnapshotMessage = {
      id: messageId,
      role: "tool",
      content,
      toolCallId,
    };

    if (typeof event.timestamp === "number")
    {
      snapshot.timestamp = event.timestamp;
    }

    UpsertMessage(state, snapshot);
    return;
  }

  if (eventType === "CUSTOM")
  {
    const messageId = String(event.messageId ?? `custom:${state.order.length + 1}`);
    UpsertMessage(state, {
      id: messageId,
      role: "activity",
      activityType: String(event.name ?? "custom"),
      content: typeof event.value === "string" ? event.value : JSON.stringify(event.value ?? {}),
    });
    return;
  }

  if (eventType === "RAW")
  {
    const messageId = String(event.messageId ?? `raw:${state.order.length + 1}`);
    UpsertMessage(state, {
      id: messageId,
      role: "activity",
      activityType: String(event.source ?? "raw"),
      content: JSON.stringify(event.event ?? {}),
    });
    return;
  }

  if (eventType === "ACTIVITY_SNAPSHOT")
  {
    const messageId = String(event.messageId ?? `activity:${state.order.length + 1}`);
    UpsertMessage(state, {
      id: messageId,
      role: "activity",
      activityType: String(event.activityType ?? "activity"),
      content: JSON.stringify(event.content ?? {}),
    });
  }
}

export function eventsToSnapshots(events: AguiEvent[]): AguiSnapshotMessage[]
{
  const state = CreateSnapshotState();

  for (const event of events)
  {
    ApplyAguiEvent(state, event);
  }

  const dedupedOrder: string[] = [];
  const seen = new Set<string>();

  for (const messageId of state.order)
  {
    if (seen.has(messageId))
    {
      continue;
    }

    seen.add(messageId);
    dedupedOrder.push(messageId);
  }

  return dedupedOrder
    .map((messageId) => state.messages.get(messageId))
    .filter((message): message is AguiSnapshotMessage => message !== undefined);
}

